SELECT id, log_ts, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, COALESCE(context['region'], 'none') AS region_or_default, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, COALESCE(context['trace'], 'unknown') AS trace_or_default, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs WHERE log_ts < '2025-06-01'
